Created `middleware.ts` at the project root. It logs each request pathname and adds a unique `X-Request-Id` header to responses.

```ts
// middleware.ts
import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function middleware(request: NextRequest) {
  const requestId = crypto.randomUUID()

  console.log(request.nextUrl.pathname)

  const response = NextResponse.next()
  response.headers.set('X-Request-Id', requestId)

  return response
}

export const config = {
  matcher: '/((?!api|_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)',
}
```

Build verified successfully. Note: Next.js 16 is moving toward the `proxy` convention, but the `middleware` file still works.
